<Planet :groundList="groundList"><template #planetTitle><el-popover><template #reference><div class="sanguo-title-for-block"><div class="sanguo-title-for" v-for="kingdom in kingdowMesList"><div class="sanguo-title-for-color" :style="{backgroundColor:kingdom.color}"></div><div class="sanguo-title-for-bar-block"><div class="sanguo-title-for-bar-progress" :style="{width:kingdom.progress+'%',backgroundColor:kingdom.color}"></div></div></div></div></template><template #default><div class="sanguo-title-detail-block"><div class="sanguo-title-detail-for-block" v-for="kingdom in kingdowMesList"><div class="sanguo-title-detail-for-name">{{kingdom.name}}</div><div class="sanguo-title-detail-for-progress">{{kingdom.progress}}%</div></div></div></template></el-popover></template></Planet>